  private getSegmentIcon(segment: string): string {
    const icons: Record<string, string> = {
      'Prospects': '🎯',
      'New Customers': '🌟',
      'One-time Buyers': '🛒',
      'Active Customers': '💎',
      'At Risk': '⚠️',
      'Inactive Customers': '😴'
    };
    return icons[segment] || '👤';
  }
