def get_low_stock_products():
    """Obtiene productos con stock bajo según el threshold"""
    # Obtener threshold de query params
    threshold = request.args.get('threshold', default=10, type=int)

    # Validar threshold
    if threshold < 0 or not isinstance(threshold, int):
        return error_response('Threshold debe ser entero y no negativo', 400)

    # Consultar productos con stock <= threshold
    products = Product.query.filter(Product.stock <= threshold).order_by(Product.stock.asc()).all()

    # Preparar respuesta
    result = [
        {
            'id': product.id,
            'name': product.name,
            'sku': product.sku,
            'stock': product.stock,
            'restock_value': (float(product.cost) * (threshold - product.stock)) if product.cost is not None else 0.0
        }
        for product in products
    ]

    return success_response(
        data=result,
        count=len(result)
    )

