from flask import Blueprint, request, abort
from app.models import Product
from app.utils.responses import success_response, error_response
from app.database import db

bp = Blueprint('products', __name__, url_prefix='/api/products')

@bp.route('/low-stock', methods=['GET'])
def get_low_stock_products():
    """Obtiene productos con stock bajo según el threshold"""
    try:
        # Obtener threshold de query params
        threshold_str = request.args.get('threshold', default='10')
        try:
            threshold = int(threshold_str)
        except ValueError:
            abort(400, description='Threshold debe ser un número entero')

        # Validar threshold
        if threshold < 0:
            abort(400, description='Threshold debe ser un número entero no negativo')

        # Consultar productos con stock <= threshold
        products = (
            Product.query
            .filter(Product.stock <= threshold)
            .order_by(Product.stock.asc())
            .all()
        )

        # Preparar respuesta
        result = [
            {
                'id': product.id,
                'name': product.name,
                'sku': product.sku,
                'stock': product.stock,
                'restock_value': float(product.cost) * (threshold - product.stock) if product.cost is not None else 0.0
            }
            for product in products
        ]

        return success_response(data=result, count=len(result))
    except Exception as e:
        return error_response(str(e), 500)

